head.script:
scwin.fn_close = function(arg) {
    window.al = "test ==>" + arg;
    console.log("test ==>" + arg);
    return true;
}
scwin.trigger1_onclick = function(e) {
    //windowContainer1_subWindow0_close
    windowContainer1.createWindow("test1", null, "", "test1", "id1", "newWindow", "scwin.fn_close");
};
scwin.trigger2_onclick = function(e) {
    ///temp/jsonToXml.xml
    windowContainer1.createWindow("test2", null, "", "test2", "id1", "newWindow", "scwin.fn_close");
};
scwin.__isShowConsole = function(val) {
    return window.al == val;
}
scwin.__isShow = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    return (el) ? true : false;
}
scwin.__triggerClick = function(id) {
    return WebSquare.wUnit.getDomById($p.id + id).click();
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행하고 'open1'버튼과 'open2'버튼을 클릭한다.
    //1. Run the sample file and click the 'open1' and 'open2' buttons.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 1. test1화면과 test2화면이 보여진다.
    //1. The test1 screen and the test2 screen are displayed.
    WebSquare.wUnit.addCommand("assert", "scwin.__isShow('windowContainer1_subWindow0')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__isShow('windowContainer1_subWindow1')", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 2. F12를 실행하여 console화면이 열려있는 상태에서 test1화면과 test2화면의 창을 닫는다.
    //2. Run F12 to close the test1 and test2 windows with the console window open.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 2. test1화면을 닫을때는 console창에 'test==>test1'이 보여지고 test2화면을 닫을때는 console창에 'test==>test2'이 보여진다.
    //2. When closing the test1 screen, 'test ==> test1' is displayed in the console window and 'test ==> test2' is displayed in the console window when closing the test2 screen.
    //WebSquare.wUnit.addCommand("set", "windowContainer1_subWindow0_close.click()");
    //mobile
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('windowContainer1').closeWindow();");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowConsole('test ==>test1')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "windowContainer1_subWindow1_close.click()");
    //mobile
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('windowContainer1').closeWindow();");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowConsole('test ==>test2')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //windowContainer1.createWindow( "test" , null , "/temp/jsonToXml.xml" , "test" , "id1" , "existWindow" , "fn_close" );
    window.al = undefined;
    //Function unitTest
    //Created By: Sang.do
    //Created By: 08-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
